insert into public.site_sections (key,eyebrow,title,body,cta_label,cards,launch,texts,media) values ('hero','{"en":"Web-development & business-analysis","uk":"Web-development & business-analysis"}','{"en":"Web solutions built around your business requirements","uk":"Web solutions built around your business requirements"}','{"en":"ONVORX helps B2B companies plan, build and grow websites and digital solutions — from formalizing requirements and implementation through to ongoing support.","uk":"ONVORX helps B2B companies plan, build and grow websites and digital solutions — from formalizing requirements and implementation through to ongoing support."}','{"en":"Request an Estimate","uk":"Request an Estimate"}','[{"icon":{"kind":"asset","src":"/assets/icons/hero-target-red.svg"},"title":{"en":"Business Goals","uk":"Business Goals"},"text":{"en":"Define outcomes","uk":"Define outcomes"}},{"icon":{"kind":"asset","src":"/assets/icons/hero-users-white.svg"},"title":{"en":"User Needs","uk":"User Needs"},"text":{"en":"Understand users","uk":"Understand users"}},{"icon":{"kind":"asset","src":"/assets/icons/hero-document-white.svg"},"title":{"en":"Requirements","uk":"Requirements"},"text":{"en":"Scope & prioritize","uk":"Scope & prioritize"}},{"icon":{"kind":"asset","src":"/assets/icons/hero-sitemap-white.svg"},"title":{"en":"Strategy","uk":"Strategy"},"text":{"en":"Plan & align","uk":"Plan & align"}}]'::jsonb,'{"icon":{"kind":"asset","src":"/assets/icons/hero-launch-check-circle-red.svg"},"title":{"en":"Launch","uk":"Launch"},"text":{"en":"Test, deploy & evolve","uk":"Test, deploy & evolve"}}'::jsonb,null,null);
