insert into public.site_sections (key,eyebrow,title,body,cta_label,cards,launch,texts,media) values ('howWork','{"en":"How we work","uk":"How we work"}','{"en":"A clear path from task to implementation","uk":"A clear path from task to implementation"}','{"en":"ONVORX can join a project at the stage where support is needed — from clarifying requirements to implementation and further development.","uk":"ONVORX can join a project at the stage where support is needed — from clarifying requirements to implementation and further development."}',null,'[{"icon":{"kind":"asset","src":"/assets/icons/howwork-doc-search-white.svg"},"title":{"en":"Define","uk":"Define"},"text":{"en":"We review the business context, available designs, current solution and requirements to define what needs to be implemented.","uk":"We review the business context, available designs, current solution and requirements to define what needs to be implemented."},"sub":{"en":"Understand the task and requirements","uk":"Understand the task and requirements"}},{"icon":{"kind":"asset","src":"/assets/icons/howwork-checklist-white.svg"},"title":{"en":"Estimate","uk":"Estimate"},"text":{"en":"We define the implementation scope, dependencies and approach needed to prepare a project estimate.","uk":"We define the implementation scope, dependencies and approach needed to prepare a project estimate."},"sub":{"en":"Clarify scope and approach","uk":"Clarify scope and approach"}},{"icon":{"kind":"asset","src":"/assets/icons/howwork-code-window-white.svg"},"title":{"en":"Implement","uk":"Implement"},"text":{"en":"We develop the agreed solution, handle required integrations and test the implementation before launch.","uk":"We develop the agreed solution, handle required integrations and test the implementation before launch."},"sub":{"en":"Build, integrate and test","uk":"Build, integrate and test"}},{"icon":{"kind":"asset","src":"/assets/icons/howwork-headset-white.svg"},"title":{"en":"Support & Develop","uk":"Support & Develop"},"text":{"en":"ONVORX can support the solution after launch, implement improvements and continue its further development.","uk":"ONVORX can support the solution after launch, implement improvements and continue its further development."},"sub":{"en":"Continue after launch when needed","uk":"Continue after launch when needed"}}]'::jsonb,null,null,null);
insert into public.site_sections (key,eyebrow,title,body,cta_label,cards,launch,texts,media) values ('about','{"en":"About ONVORX","uk":"About ONVORX"}','{"en":"Practical experience behind every project","uk":"Practical experience behind every project"}','{"en":"ONVORX combines hands-on web development experience with a structured approach to requirements, implementation and ongoing development.","uk":"ONVORX combines hands-on web development experience with a structured approach to requirements, implementation and ongoing development."}',null,'[{"icon":{"kind":"asset","src":"/assets/icons/about-calendar-red.svg"},"title":{"en":"Since 2023","uk":"Since 2023"},"text":{"en":"Hands-on web development experience.","uk":"Hands-on web development experience."}},{"icon":{"kind":"asset","src":"/assets/icons/about-folder-red.svg"},"title":{"en":"Real project work","uk":"Real project work"},"text":{"en":"Experience across WordPress, WooCommerce extensions and front-end implementation.","uk":"Experience across WordPress, WooCommerce extensions and front-end implementation."}},{"icon":{"kind":"asset","src":"/assets/icons/about-doc-search-red.svg"},"title":{"en":"Beyond implementation","uk":"Beyond implementation"},"text":{"en":"Requirements and business processes are the foundation before development begins.","uk":"Requirements and business processes are the foundation before development begins."}}]'::jsonb,null,null,null);
insert into public.site_sections (key,eyebrow,title,body,cta_label,cards,launch,texts,media) values ('cta','{"en":"Start a project","uk":"Start a project"}','{"en":"Let’s turn your requirements into a working solution","uk":"Let’s turn your requirements into a working solution"}','{"en":"Tell us what you’re planning, what already exists and where support is needed. ONVORX will review the requirements and clarify what’s needed to prepare a project estimate.","uk":"Tell us what you’re planning, what already exists and where support is needed. ONVORX will review the requirements and clarify what’s needed to prepare a project estimate."}','{"en":"Request a Project Estimate","uk":"Request a Project Estimate"}',null,null,null,null);
