insert into public.site_sections (key,eyebrow,title,body,cta_label,cards,launch,texts,media) values ('svcWebDevelopment','{"en":"","uk":""}','{"en":"Web Development","uk":"Web Development"}','{"en":"Turn your designs and requirements into a website with the structure, features and integrations your business needs.","uk":"Turn your designs and requirements into a website with the structure, features and integrations your business needs."}','{"en":"Get a project estimate","uk":"Get a project estimate"}','[{"icon":{"kind":"asset","src":"/assets/services-page/icons/code.svg"},"title":{"en":"Design implementation","uk":"Design implementation"},"text":{"en":"Build website pages from your approved design.","uk":"Build website pages from your approved design."}},{"icon":{"kind":"asset","src":"/assets/services-page/icons/cms.svg"},"title":{"en":"Content management","uk":"Content management"},"text":{"en":"Set up tools for your team to edit and publish content.","uk":"Set up tools for your team to edit and publish content."}},{"icon":{"kind":"asset","src":"/assets/services-page/icons/code.svg"},"title":{"en":"Responsive behavior","uk":"Responsive behavior"},"text":{"en":"Adapt layouts and interactions for desktop, tablet and mobile.","uk":"Adapt layouts and interactions for desktop, tablet and mobile."}},{"icon":{"kind":"asset","src":"/assets/services-page/icons/layout.svg"},"title":{"en":"Structure & navigation","uk":"Structure & navigation"},"text":{"en":"Organize pages, content and user journeys before development.","uk":"Organize pages, content and user journeys before development."}},{"icon":{"kind":"asset","src":"/assets/services-page/icons/nodes.svg"},"title":{"en":"Integrations","uk":"Integrations"},"text":{"en":"Connect forms, external tools and business systems.","uk":"Connect forms, external tools and business systems."}},{"icon":{"kind":"asset","src":"/assets/services-page/icons/launch.svg"},"title":{"en":"Testing & launch","uk":"Testing & launch"},"text":{"en":"Check agreed features and prepare the website to go live.","uk":"Check agreed features and prepare the website to go live."}}]'::jsonb,null,'{"tags":[{"en":"WordPress","uk":"WordPress"},{"en":"Webflow","uk":"Webflow"},{"en":"Framer","uk":"Framer"}],"get":{"title":{"en":"A responsive website, ready to launch","uk":"A responsive website, ready to launch"},"text":{"en":"Your approved design brought to life: featuring editable content and the integrations essential for your business.","uk":"Your approved design brought to life: featuring editable content and the integrations essential for your business."}}}'::jsonb,'{"badge":{"kind":"asset","src":"/assets/services-page/badge-web.webp"},"picture":{"kind":"asset","src":"/assets/services-page/picture-web.webp"}}'::jsonb);
insert into public.site_sections (key,eyebrow,title,body,cta_label,cards,launch,texts,media) values ('svcAiBuild','{"en":"New","uk":"New"}','{"en":"AI Build","uk":"AI Build"}','{"en":"One connected workflow from a Figma design to a live, editable website. We set up the site, an admin panel and a Telegram bot on a single shared database, so your team can update content without touching code.","uk":"One connected workflow from a Figma design to a live, editable website. We set up the site, an admin panel and a Telegram bot on a single shared database, so your team can update content without touching code."}','{"en":"View project example","uk":"View project example"}',null,null,'{"stack":[{"en":"Design","uk":"Design"},{"en":"Site","uk":"Site"},{"en":"Database","uk":"Database"},{"en":"Admin Panel","uk":"Admin Panel"},{"en":"Telegram bot","uk":"Telegram bot"}]}'::jsonb,'{"site":{"kind":"asset","src":"/assets/services-page/ai-mockup-site.webp"},"admin":{"kind":"asset","src":"/assets/services-page/ai-mockup-admin.webp"},"bot":{"kind":"asset","src":"/assets/services-page/ai-mockup-bot.webp"}}'::jsonb);
insert into public.site_sections (key,eyebrow,title,body,cta_label,cards,launch,texts,media) values ('svcWebsiteSupport','{"en":"","uk":""}','{"en":"Website Support & Development","uk":"Website Support & Development"}','{"en":"New pages, functionality and integrations for a site that is already live, delivered in agreed releases.","uk":"New pages, functionality and integrations for a site that is already live, delivered in agreed releases."}','{"en":"Plan your next release","uk":"Plan your next release"}','[{"icon":{"kind":"asset","src":"/assets/services-page/icons/pages.svg"},"title":{"en":"New pages","uk":"New pages"},"text":{"en":"Extend your website with new pages and landing pages.","uk":"Extend your website with new pages and landing pages."}},{"icon":{"kind":"asset","src":"/assets/services-page/icons/gear.svg"},"title":{"en":"Functionality","uk":"Functionality"},"text":{"en":"Add or refine features on your existing website.","uk":"Add or refine features on your existing website."}},{"icon":{"kind":"asset","src":"/assets/services-page/icons/integration.svg"},"title":{"en":"Integrations","uk":"Integrations"},"text":{"en":"Connect your website to external tools and business systems.","uk":"Connect your website to external tools and business systems."}},{"icon":{"kind":"asset","src":"/assets/services-page/icons/wrench.svg"},"title":{"en":"Ongoing support","uk":"Ongoing support"},"text":{"en":"Maintain and improve your website at an agreed pace.","uk":"Maintain and improve your website at an agreed pace."}},{"icon":{"kind":"asset","src":"/assets/services-page/icons/clock.svg"},"title":{"en":"Release cycle","uk":"Release cycle"},"text":{"en":"Group changes into planned releases with a clear scope for each one.","uk":"Group changes into planned releases with a clear scope for each one."}},{"icon":{"kind":"asset","src":"/assets/services-page/icons/plug.svg"},"title":{"en":"Taking over an existing site","uk":"Taking over an existing site"},"text":{"en":"Pick up a project built by another team, with access and hosting set in order.","uk":"Pick up a project built by another team, with access and hosting set in order."}}]'::jsonb,null,'{"tags":[{"en":"WordPress","uk":"WordPress"},{"en":"Webflow","uk":"Webflow"},{"en":"Framer","uk":"Framer"}],"get":{"title":{"en":"Website improvements, delivered in planned releases","uk":"Website improvements, delivered in planned releases"},"text":{"en":"New pages, features and integrations - tested and delivered in agreed releases.","uk":"New pages, features and integrations - tested and delivered in agreed releases."}}}'::jsonb,'{"badge":{"kind":"asset","src":"/assets/services-page/badge-support.webp"},"picture":{"kind":"asset","src":"/assets/services-page/picture-support.webp"}}'::jsonb);
insert into public.site_sections (key,eyebrow,title,body,cta_label,cards,launch,texts,media) values ('svcBusinessAnalysis','{"en":"","uk":""}','{"en":"Business Analysis","uk":"Business Analysis"}','{"en":"Understand your processes, clarify business needs and turn them into clear requirements for implementation.","uk":"Understand your processes, clarify business needs and turn them into clear requirements for implementation."}','{"en":"Discuss your requirements","uk":"Discuss your requirements"}','[{"icon":{"kind":"asset","src":"/assets/services-page/icons/integration.svg"},"title":{"en":"Analyze the process and identify bottlenecks","uk":"Analyze the process and identify bottlenecks"},"text":{"en":"Map steps and roles to uncover delays, data issues and duplicated work.","uk":"Map steps and roles to uncover delays, data issues and duplicated work."},"track":0},{"icon":{"kind":"asset","src":"/assets/services-page/icons/target.svg"},"title":{"en":"Define the target process","uk":"Define the target process"},"text":{"en":"Describe how the process should run once the change is in place.","uk":"Describe how the process should run once the change is in place."},"track":0},{"icon":{"kind":"asset","src":"/assets/services-page/icons/doc.svg"},"title":{"en":"Prepare requirements for automation","uk":"Prepare requirements for automation"},"text":{"en":"Turn the target process into clear requirements for implementation.","uk":"Turn the target process into clear requirements for implementation."},"track":0},{"icon":{"kind":"asset","src":"/assets/services-page/icons/chat.svg"},"title":{"en":"Clarify the business need","uk":"Clarify the business need"},"text":{"en":"Define what the software needs to achieve and who it should serve.","uk":"Define what the software needs to achieve and who it should serve."},"track":1},{"icon":{"kind":"asset","src":"/assets/services-page/icons/list.svg"},"title":{"en":"Document system and integration requirements","uk":"Document system and integration requirements"},"text":{"en":"Organize requirements by function, priority and dependency, including data exchange with existing systems.","uk":"Organize requirements by function, priority and dependency, including data exchange with existing systems."},"track":1},{"icon":{"kind":"asset","src":"/assets/services-page/icons/doc-check.svg"},"title":{"en":"Align business and implementation teams","uk":"Align business and implementation teams"},"text":{"en":"Keep both sides aligned on scope, decisions and changes throughout implementation.","uk":"Keep both sides aligned on scope, decisions and changes throughout implementation."},"track":1}]'::jsonb,null,'{"tags":[{"en":"Two tracks","uk":"Two tracks"},{"en":"Requirements","uk":"Requirements"},{"en":"Specifications","uk":"Specifications"}],"get":{"title":{"en":"Clear requirements for confident implementation","uk":"Clear requirements for confident implementation"},"text":{"en":"Documented processes, prioritized requirements and agreed scope — so your team knows what to build, why it matters and how to verify the result.","uk":"Documented processes, prioritized requirements and agreed scope — so your team knows what to build, why it matters and how to verify the result."}},"tracks":[{"label":{"en":"Track 01","uk":"Track 01"},"title":{"en":"Business Process Analysis","uk":"Business Process Analysis"}},{"label":{"en":"Track 02","uk":"Track 02"},"title":{"en":"IT Business Analysis","uk":"IT Business Analysis"}}]}'::jsonb,'{"badge":{"kind":"asset","src":"/assets/services-page/badge-analysis.webp"},"picture":{"kind":"asset","src":"/assets/services-page/picture-analysis.webp"}}'::jsonb);
